s['crayon-wave']=r'''
let marks=[],current=[];
const scene={tap(){current=[];marks.push(current);if(marks.length>12)marks.shift();current.push([state.x*1000,state.y*700]);},move(){if(state.held){current.push([state.x*1000,state.y*700]);if(current.length>240)current.shift();}},draw(){const t=state.time;for(let y=170;y<=560;y+=65)line([[110,y],[890,y]],INK+'0c',1);for(let k=0;k<3;k++){for(let pass=0;pass<5;pass++){const pts=[];for(let i=0;i<=180;i++){const x=110+i*4.3,j=(rnd(i+pass*500+k*91)-.5)*9,y=270+k*90+Math.sin(x*.017+t*1.4+k*.8)*(60+state.y*40)+j+(pass-2)*3;pts.push([x,y]);}line(pts,C[k]+(pass===2?'d0':'65'),3);}const x=140+k*46,y=590;ctx.save();ctx.translate(x,y);ctx.rotate(-.4);rect(-10,-35,20,70,C[k],3);rect(-11,-16,22,38,'#fff2df75',1);line([[-11,-11],[11,-11]],C[k],2);ctx.beginPath();ctx.moveTo(-10,-35);ctx.lineTo(0,-54);ctx.lineTo(10,-35);ctx.closePath();ctx.fillStyle=C[k];ctx.fill();ctx.restore();}marks.forEach((pts,i)=>{if(pts.length>1){line(pts,C[(i+3)%4]+'a0',6);line(pts.map(([x,y],j)=>[x+Math.sin(j)*2,y+Math.cos(j)*2]),C[(i+3)%4]+'70',3);}});text('THE HAND IS ALLOWED TO WANDER',560,630,11,INK+'80');}};
'''
s['spring-dancer']=r'''
const dancers=Array.from({length:5},(_,i)=>({h:175,v:0,target:175}));
const scene={tap(){const i=clamp(Math.floor(state.x*5),0,4);dancers[i].v-=290;dancers[(i+1)%5].v+=140;},beat(i){dancers[i%5].v+=240;dancers[(i+2)%5].v-=140;},update(dt){for(let i=0;i<5;i++){const d=dancers[i],target=170+Math.sin(state.time*2+i)*20+(state.y-.5)*55;d.v+=(target-d.h)*dt*45;d.v*=Math.exp(-dt*4);d.h=clamp(d.h+d.v*dt,88,290);}},draw(){line([[110,552],[890,552]],INK+'30',2);for(let i=0;i<5;i++){const x=210+i*145,d=dancers[i],y=520-d.h,w=28+(175-d.h)*.06;ellipse(x,557,38,7,INK+'13');rect(x-35,527,30,16,INK,8);rect(x+5,527,30,16,INK,8);line([[x-13,525],[x-16,505]],INK,3);line([[x+13,525],[x+16,505]],INK,3);const pts=[];for(let j=0;j<=180;j++){const p=j/180;pts.push([x+Math.sin(p*TAU*9)*w,y+25+p*(d.h-42)]);}line(pts,INK+'20',9);line(pts,C[i%4],6);circle(x,y,32,C[i%4]);circle(x-9,y-3,3,INK);circle(x+9,y-3,3,INK);ctx.beginPath();ctx.arc(x,y+5,10,.2,Math.PI-.2);ctx.strokeStyle=INK;ctx.lineWidth=2;ctx.stroke();const lift=(175-d.h)*.25;line([[x-w,y+55],[x-w-26,y+79-lift]],INK,3);line([[x+w,y+55],[x+w+26,y+79-lift]],INK,3);circle(x-w-26,y+79-lift,5,C[i%4]);circle(x+w+26,y+79-lift,5,C[i%4]);text(String(i+1).padStart(2,'0'),x,608,11,INK+'80');}text('PASS A LITTLE ELASTICITY ALONG',500,655,11,INK+'80');}};
'''
